// Arma el aviso de WhatsApp (API oficial de Meta, mensaje de plantilla) con todos los avisos graves pendientes.
// De noche (fuera de hora_inicio..hora_fin, hora de Monterrey) no manda nada: los avisos se quedan
// pendientes y salen juntos, como resumen, en la primera vuelta despues de hora_inicio.
const CANAL = 'whatsapp';
const cfg = $('Configuracion').first().json;
const pendientes = ($input.first().json.pendientes ?? []).filter((p) => p.canal === CANAL);
const hora = Number(new Intl.DateTimeFormat('en-US', { timeZone: 'America/Monterrey', hour: 'numeric', hourCycle: 'h23' }).format(new Date()));
if (pendientes.length === 0 || hora < cfg.hora_inicio || hora >= cfg.hora_fin) return [];

const NOMBRE = { temperatura: 'Temperatura fuera de rango', humedad: 'Humedad fuera de rango', puerta_abierta: 'Puerta abierta de mas', nodo_sin_reporte: 'Nodo sin reportar', sensor_falla: 'Falla de sensor', golpe: 'Golpe en el anaquel', movimiento_fuera_de_horario: 'Movimiento fuera de horario', luz: 'Luz fuera de horario' };
const UNIDAD = { temperatura: ' C', humedad: ' % HR' };
const fmt = new Intl.DateTimeFormat('es-MX', { timeZone: 'America/Monterrey', day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' });
const lineas = pendientes.map((p) => {
  const valor = UNIDAD[p.tipo] && p.valor !== null ? ' (' + p.valor + UNIDAD[p.tipo] + ')' : '';
  const estado = p.ts_fin ? 'ya se resolvio' : 'SIGUE ACTIVA';
  return '- ' + (NOMBRE[p.tipo] ?? p.tipo) + valor + ', nodo ' + p.id_nodo + ', desde ' + fmt.format(new Date(p.ts_inicio)) + ': ' + estado;
});
const titulo = pendientes.length === 1 ? '1 alerta grave' : pendientes.length + ' alertas graves';
// La plantilla de Meta recibe UN parametro de texto: sin saltos de linea ni tabuladores, sin 4 espacios seguidos.
let texto = (titulo + ': ' + lineas.map((l) => l.replace(/^- /, '')).join(' | ')).split(/[^!-~¡-ÿ]+/).filter(Boolean).join(' ');
if (texto.length > 900) texto = texto.slice(0, 897) + '...';
const telefonos = String(cfg.meta_telefonos ?? '').split(',').map((t) => t.replace(/[^0-9]/g, '')).filter((t) => t.length >= 10);
if (telefonos.length === 0) throw new Error('Configuracion.meta_telefonos esta vacio o mal escrito');
// Una salida por destinatario: Meta manda a un numero por peticion.
return telefonos.map((to) => ({ json: { canal: CANAL, ids: pendientes.map((p) => p.id_alerta), to, texto } }));
